import sys

class CaesarCipher:
    def __init__(self, shift):
        self.shift = shift % 26

    def encrypt(self, text):
        return self._transform(text, self.shift)

    def decrypt(self, text):
        return self._transform(text, -self.shift)

    def _transform(self, text, shift):
        result = []
        for char in text:
            if char.isalpha():
                base = ord('A') if char.isupper() else ord('a')
                result.append(chr((ord(char) - base + shift) % 26 + base))
            else:
                result.append(char)
        return ''.join(result)

    @staticmethod
    def brute_force(text):
        for shift in range(1, 26):
            cc = CaesarCipher(shift)
            print(f'Shift {shift}: {cc.decrypt(text)}')

if __name__ == '__main__':
    if len(sys.argv) < 3:
        print('Usage: python caesar.py <mode> <text> [shift]')
        print('Modes: encrypt, decrypt, brute')
        sys.exit(1)

    mode = sys.argv[1]
    text = sys.argv[2]

    if mode == 'brute':
        CaesarCipher.brute_force(text)
    else:
        if len(sys.argv) < 4:
            print('Shift is required for encrypt and decrypt modes')
            sys.exit(1)
        shift = int(sys.argv[3])
        cc = CaesarCipher(shift)
        if mode == 'encrypt':
            print(cc.encrypt(text))
        elif mode == 'decrypt':
            print(cc.decrypt(text))
        else:
            print('Unknown mode')
            sys.exit(1)
